"use client";
import * as React from "react";
import { cn } from "../lib/cn";

export interface ScrollAreaProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Welke richting mag scrollen. */
  orientation?: "vertical" | "horizontal" | "both";
  /** Vaste hoogte; zonder dit bepaalt de ouder de hoogte. */
  height?: number | string;
  maxHeight?: number | string;
  /** Vervaging aan de randen zolang er meer inhoud is (standaard aan). */
  fade?: boolean;
  /** Balk blijft altijd zichtbaar in plaats van alleen bij hoveren. */
  alwaysVisible?: boolean;
}

/**
 * ScrollArea — scrollbaar vlak met een smalle, ingetogen scrollbalk en
 * vervaging aan de randen zolang er meer inhoud is.
 *
 * De balk is de echte scrollbalk van de browser, alleen anders opgemaakt:
 * zo blijven vegen, scrollwiel en toetsenbord werken zoals gebruikers verwachten.
 */
export const ScrollArea = React.forwardRef<HTMLDivElement, ScrollAreaProps>(function ScrollArea(
  { orientation = "vertical", height, maxHeight, fade = true, alwaysVisible, className, children, style, onScroll, ...rest },
  ref
) {
  const eigen = React.useRef<HTMLDivElement | null>(null);
  const [randen, setRanden] = React.useState({ boven: false, onder: false, links: false, rechts: false });

  const meet = React.useCallback(() => {
    const node = eigen.current;
    if (!node || !fade) return;
    const speling = 2;
    setRanden({
      boven: node.scrollTop > speling,
      onder: node.scrollTop + node.clientHeight < node.scrollHeight - speling,
      links: node.scrollLeft > speling,
      rechts: node.scrollLeft + node.clientWidth < node.scrollWidth - speling,
    });
  }, [fade]);

  React.useEffect(() => {
    meet();
    const node = eigen.current;
    if (!node || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(meet);
    observer.observe(node);
    for (const kind of Array.from(node.children)) observer.observe(kind);
    return () => observer.disconnect();
  }, [meet, children]);

  return (
    <div
      ref={(node) => {
        eigen.current = node;
        if (typeof ref === "function") ref(node as HTMLDivElement);
        else if (ref) (ref as React.RefObject<HTMLDivElement | null>).current = node;
      }}
      className={cn("lui-scroll-area", `lui-scroll-${orientation}`, alwaysVisible && "lui-scroll-visible", className)}
      style={{ height, maxHeight, ...style }}
      data-fade-top={fade && randen.boven ? "" : undefined}
      data-fade-bottom={fade && randen.onder ? "" : undefined}
      data-fade-left={fade && randen.links ? "" : undefined}
      data-fade-right={fade && randen.rechts ? "" : undefined}
      onScroll={(event) => {
        onScroll?.(event);
        meet();
      }}
      {...rest}
    >
      {children}
    </div>
  );
});

/* ============================ ScrollArea ============================ */
.lui-scroll-area {
  --lui-scroll-duim: color-mix(in srgb, var(--text) 22%, transparent);
  position: relative; min-height: 0; overflow: auto;
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
  transition: scrollbar-color var(--dur) var(--ease);
  overscroll-behavior: contain;
}
.lui-scroll-vertical { overflow-x: hidden; overflow-y: auto; }
.lui-scroll-horizontal { overflow-x: auto; overflow-y: hidden; }

/* De balk verschijnt bij hoveren of zodra je erin scrollt met het toetsenbord. */
.lui-scroll-area:hover,
.lui-scroll-area:focus-within,
.lui-scroll-visible { scrollbar-color: var(--lui-scroll-duim) transparent; }

.lui-scroll-area::-webkit-scrollbar { width: 10px; height: 10px; }
.lui-scroll-area::-webkit-scrollbar-track { background: transparent; }
.lui-scroll-area::-webkit-scrollbar-thumb {
  background: transparent; border-radius: var(--r-full);
  border: 3px solid transparent; background-clip: content-box;
  transition: background var(--dur) var(--ease);
}
.lui-scroll-area:hover::-webkit-scrollbar-thumb,
.lui-scroll-area:focus-within::-webkit-scrollbar-thumb,
.lui-scroll-visible::-webkit-scrollbar-thumb {
  background: var(--lui-scroll-duim); background-clip: content-box;
}
.lui-scroll-area::-webkit-scrollbar-thumb:hover {
  background: color-mix(in srgb, var(--text) 38%, transparent); background-clip: content-box;
}
.lui-scroll-area::-webkit-scrollbar-corner { background: transparent; }

/* Vervaging aan de rand waar nog inhoud zit. */
.lui-scroll-area[data-fade-top],
.lui-scroll-area[data-fade-bottom],
.lui-scroll-area[data-fade-left],
.lui-scroll-area[data-fade-right] {
  -webkit-mask-composite: source-in;
  mask-composite: intersect;
}
.lui-scroll-area[data-fade-top] { mask-image: linear-gradient(to bottom, transparent 0, #000 22px); }
.lui-scroll-area[data-fade-bottom] { mask-image: linear-gradient(to top, transparent 0, #000 22px); }
.lui-scroll-area[data-fade-top][data-fade-bottom] {
  mask-image: linear-gradient(to bottom, transparent 0, #000 22px, #000 calc(100% - 22px), transparent 100%);
}
.lui-scroll-area[data-fade-left] { mask-image: linear-gradient(to right, transparent 0, #000 22px); }
.lui-scroll-area[data-fade-right] { mask-image: linear-gradient(to left, transparent 0, #000 22px); }
.lui-scroll-area[data-fade-left][data-fade-right] {
  mask-image: linear-gradient(to right, transparent 0, #000 22px, #000 calc(100% - 22px), transparent 100%);
}
